package com.bank.total;

import java.util.*;
import java.util.logging.*;
import java.util.stream.IntStream;

public class SideEffectDemo {
    private static final Logger log = Logger.getLogger("Total");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> amounts = IntStream.rangeClosed(1, 1000).boxed().toList();
        TotalService service = new TotalService();

        log.warning(() -> "buggy mutating map (parallel): " + service.buggyTotal(amounts)
            + " (expected 500500; often wrong due to race)");
        log.info(() -> "pure reduce (correct)         : " + service.correctTotal(amounts));
    }
}

// ─── Would be in service/TotalService.java ───
class TotalService {
    // BUG: side-effect (mutating shared field) inside map, run in parallel → race
    private long runningTotal = 0;
    long buggyTotal(List<Integer> amounts) {
        runningTotal = 0;
        amounts.parallelStream()
            .map(n -> { runningTotal += n; return n; })   // SIDE EFFECT on shared state
            .forEach(n -> {});
        return runningTotal;                              // non-deterministic / wrong
    }

    // FIX: pure reduction — no external state
    long correctTotal(List<Integer> amounts) {
        return amounts.parallelStream()
            .mapToLong(Integer::longValue)
            .sum();                                        // associative, side-effect-free
    }
}
